function show(label, o, n) {
  print(label, "|| zod3:", o.ok ? "ACCEPT " + JSON.stringify(o.value) : "reject " + JSON.stringify(o.problems), "|| now:", n.ok ? "ACCEPT " + JSON.stringify(n.value) : "reject " + JSON.stringify(n.problems));
}
