try {
  const s = zod3.z.string().ip();
  for (const ip of ["fe80::1%eth0", "305b:7432:e22d:4c35:1962:71c6:ed4d:69ae%1", "::%1", "fe80::1"]) print(ip, "->", s.safeParse(ip).success);
} catch (e) { print("raw err", e.message); }
print("=== config.hosts ===");
for (const hosts of [["fe80::1%eth0"], ["2459::52d2%lo0"], ["26.42.49.219"]]) {
  const inp = { hosts: hosts };
  show(JSON.stringify(hosts), oracle.parseConfig(inp), main.parseConfig(inp));
}
print("=== config.timeoutMs ===");
for (const t of [Infinity, -Infinity, NaN, 5000]) {
  const inp = { hosts: ["1.2.3.4"], timeoutMs: t };
  show("timeoutMs=" + String(t), oracle.parseConfig(inp), main.parseConfig(inp));
}
print("=== signup.age ===");
for (const age of [1e21, 9007199254740994, 1.7976931348623157e308, 42]) {
  const inp = Object.assign({}, base, { age: age });
  show("age=" + String(age), oracle.parseSignup(inp), main.parseSignup(inp));
}
print("=== signup.website ===");
for (const w of ["https://example.com\n", " https://example.com", "https://example.com"]) {
  const inp = Object.assign({}, base, { website: w });
  const o = oracle.parseSignup(inp), n = main.parseSignup(inp);
  print(JSON.stringify(w), "|| zod3:", o.ok ? JSON.stringify(o.value.website) : "reject", "|| now:", n.ok ? JSON.stringify(n.value.website) : "reject");
}

