          "probe": "const S=a=>({id:'123e4567-e89b-12d3-a456-426614174000',email:'a@b.com',name:'x',ip:'1.2.3.4',plan:'free',flags:{},age:a});const r=x=>String(x)+'='+(oracle.parseSignup(S(x)).ok?'A':'R')+'/'+(main.parseSignup(S(x)).ok?'A':'R');print(r(9007199254740994)+' '+r(1e21)+' '+r(42));print('msg='+String(main.parseSignup(S(1e21)).problems));",
